package org.sleepwell.app;

import android.content.*;
import android.os.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

/** Only isolated SQLite and owned fixture bytes. No scheduler, service or hardware port. */
public final class BackupStorageTest {
    private final Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();
    static final class Transport implements BackupDocuments.Transport {byte[] input,output;int opens,writes,cancels;public InputStream input(String uri){assertNotSame(Looper.getMainLooper(),Looper.myLooper());opens++;return new ByteArrayInputStream(input);}public OutputStream output(String uri){assertNotSame(Looper.getMainLooper(),Looper.myLooper());writes++;return new ByteArrayOutputStream(){@Override public void close(){output=toByteArray();}};}public void cancel(){cancels++;}}
    private BackupDocuments work(SoundLabelFixture fixture,Transport transport,AtomicInteger retired){return new BackupDocuments(context,c->fixture.open(),transport,new BackupDocuments.Effects(){public void idle(long expected){BackupRuntime.requireIdle(context,expected);}public void retired(List<Alarm> old,Store current){retired.incrementAndGet();}public void recover(Store store){SoundClips.recover(context,store);}});}
    private void idle(){assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(context,"ringing"));assertFalse(Prefs.flag(context,"tracking"));}
    private void seedNap(Store store){Alarm nap=new Alarm(91);nap.enabled=true;nap.nap=new NapPlan(UUID.randomUUID().toString(),"backup-private",System.currentTimeMillis()+60000,100000,3,20,true,NapPlan.Phase.PENDING,"");store.save(nap);}
    @Test public void exportedBytesArePortableReviewedRestoreKeepsLabelsAndNapsInactive()throws Exception {idle();Map<String,?> preferences=new HashMap<>(Prefs.of(context).getAll());try(SoundLabelFixture fixture=new SoundLabelFixture(context);Store store=fixture.open()){
        seedNap(store);SoundLabels.save(store,fixture.snapshot(store),"speech");Transport transport=new Transport();AtomicInteger retired=new AtomicInteger();BackupDocuments work=work(fixture,transport,retired);work.write(BackupJob.Kind.JSON,"content://fixture/output",()->true);assertEquals(1,transport.writes);transport.input=transport.output;JSONObject portable=new JSONObject(new String(transport.input,java.nio.charset.StandardCharsets.UTF_8));assertEquals(4,portable.getInt("format"));assertFalse(new String(transport.input,java.nio.charset.StandardCharsets.UTF_8).contains(fixture.file.getName()));BackupJob.Review review=work.read("content://fixture/input",()->true);assertTrue(review.summary.contains("1 user labels"));assertTrue(fixture.file.exists());String result=work.restore(review);assertTrue(result.startsWith("Data restored."));assertEquals(1,retired.get());assertFalse(fixture.file.exists());try(Store reopened=fixture.open()){Alarm nap=reopened.alarm(91);assertNotNull(nap);assertFalse(nap.enabled);assertEquals(NapPlan.Phase.CANCELLED,nap.nap.phase);JSONObject event=fixture.event(reopened);assertEquals("snoring",event.getString("category"));assertEquals("speech",event.getString("user_category"));assertTrue(event.isNull("clip"));assertEquals(0,reopened.rows("SELECT clip FROM pending_clip_deletes").size());}
        work.write(BackupJob.Kind.CSV,"content://fixture/csv",()->true);assertEquals(Records.csv(store),new String(transport.output,java.nio.charset.StandardCharsets.UTF_8));assertEquals(preferences,Prefs.of(context).getAll());
    }}
    @Test public void changedLabelsPendingJournalAndRuntimeAdmissionsRejectBeforeReplacement()throws Exception {idle();try(SoundLabelFixture fixture=new SoundLabelFixture(context);Store store=fixture.open()){
        Transport transport=new Transport();transport.input=BackupIo.encode(store.backup().toString());AtomicInteger retired=new AtomicInteger();BackupDocuments work=work(fixture,transport,retired);byte[] original=Files.readAllBytes(fixture.file.toPath());BackupJob.Review labels=work.read("content://fixture/input",()->true);SoundLabels.save(store,fixture.snapshot(store),"speech");String changed=BackupFingerprint.read(store);assertThrows(IllegalStateException.class,()->work.restore(labels));assertEquals(changed,BackupFingerprint.read(store));assertArrayEquals(original,Files.readAllBytes(fixture.file.toPath()));
        BackupJob.Review journal=work.read("content://fixture/input",()->true);store.getWritableDatabase().execSQL("INSERT INTO pending_clip_deletes VALUES(999,1,'backup-private-missing.wav',123)");String withJournal=BackupFingerprint.read(store);assertThrows(IllegalStateException.class,()->work.restore(journal));assertEquals(withJournal,BackupFingerprint.read(store));BackupJob.Review active=work.read("content://fixture/input",()->true);BackupRuntime.admitted();assertThrows(IllegalStateException.class,()->work.restore(active));assertEquals(withJournal,BackupFingerprint.read(store));assertEquals(0,retired.get());assertArrayEquals(original,Files.readAllBytes(fixture.file.toPath()));
    }}
    @Test public void admissionDuringInsertionRollsBackThenAWaitingNewRecordIsPreserved()throws Exception {idle();try(SoundLabelFixture fixture=new SoundLabelFixture(context);Store store=fixture.open()){
        JSONObject root=store.backup();seedNap(store);String before=BackupFingerprint.read(store);long admission=BackupRuntime.generation();AtomicBoolean admitted=new AtomicBoolean();AtomicReference<Throwable> failure=new AtomicReference<>();CountDownLatch started=new CountDownLatch(1);Thread recording=new Thread(()->{try{BackupRuntime.admitted();started.countDown();try(Store other=fixture.open()){long id=other.begin();other.end(id,false);}}catch(Throwable error){failure.set(error);}},"private-new-record");
        AtomicInteger checkpoints=new AtomicInteger();assertThrows(IllegalStateException.class,()->Backup.restoreData(store,root,()->{if(checkpoints.incrementAndGet()==4){assertNotEquals("Fixture must reach actual replacement writes",before,BackupFingerprint.read(store));admitted.set(true);recording.start();try{assertTrue(started.await(5,TimeUnit.SECONDS));}catch(InterruptedException interrupted){throw new IllegalStateException(interrupted);}}BackupRuntime.requireIdle(context,admission);}));
        assertTrue(admitted.get());recording.join(10000);assertFalse(recording.isAlive());assertNull(failure.get());assertNotNull("Original alarm rolled back",store.alarm(91));assertEquals(2,store.rows("SELECT id FROM sessions").size());assertEquals("Original model evidence rolled back",2,store.rows("SELECT id FROM sound_events").size());assertTrue(store.rows("SELECT clip FROM pending_clip_deletes").isEmpty());assertTrue(fixture.file.exists());
    }}
    @Test public void typedFingerprintCoversEveryAffectedTableAndExactIntegerIdentity()throws Exception {idle();try(SoundLabelFixture fixture=new SoundLabelFixture(context);Store store=fixture.open()){
        String first=BackupFingerprint.read(store);store.getWritableDatabase().execSQL("INSERT INTO record_create_requests(token,session) VALUES('pending',9007199254740992)");String one=BackupFingerprint.read(store);assertNotEquals(first,one);store.getWritableDatabase().execSQL("UPDATE record_create_requests SET session=9007199254740993 WHERE token='pending'");assertNotEquals("No lossy double JSON conversion",one,BackupFingerprint.read(store));store.getWritableDatabase().execSQL("DELETE FROM record_create_requests WHERE token='pending'");assertEquals(first,BackupFingerprint.read(store));store.getWritableDatabase().execSQL("UPDATE clips SET favorite=1");assertNotEquals(first,BackupFingerprint.read(store));
    }}
    @Test public void pendingCountAndCloseFailuresCannotHideACommittedReplacement()throws Exception {idle();for(boolean failCount:new boolean[]{false,true})try(SoundLabelFixture fixture=new SoundLabelFixture(context);Store seed=fixture.open()){
        Transport transport=new Transport();transport.input=BackupIo.encode(seed.backup().toString());AtomicBoolean committed=new AtomicBoolean();Records.Factory records=c->new Store(c,fixture.database){@Override public List<JSONObject> rows(String sql,String...args){if(failCount&&committed.get()&&sql.equals("SELECT clip FROM pending_clip_deletes"))throw new android.database.sqlite.SQLiteException("Injected postcommit count failure");return super.rows(sql,args);}@Override public synchronized void close(){super.close();if(!failCount&&committed.get())throw new android.database.sqlite.SQLiteException("Injected postcommit close failure");}};
        BackupDocuments work=new BackupDocuments(context,records,transport,new BackupDocuments.Effects(){public void idle(long admission){BackupRuntime.requireIdle(context,admission);}public void retired(List<Alarm> old,Store store){committed.set(true);}public void recover(Store store){}});BackupJob.Review review=work.read("content://fixture/input",()->true);String result=work.restore(review);assertTrue(result.startsWith("Data restored."));assertTrue(result.contains("needs attention"));assertTrue(committed.get());assertEquals("imported",seed.rows("SELECT origin FROM sessions").get(0).getString("origin"));assertTrue("Recovery was deliberately not run",fixture.file.exists());
    }}
    @Test public void defaultExclusiveReplacementBlocksOtherReadersWhileWalRawReadsCanObserveOldData()throws Exception {idle();String name="backup-contention-"+UUID.randomUUID()+".db";try{
        for(boolean wal:new boolean[]{false,true})try(Store writer=new Store(context,name);Store reader=new Store(context,name)){writer.setWriteAheadLoggingEnabled(wal);reader.setWriteAheadLoggingEnabled(wal);writer.getWritableDatabase();reader.getReadableDatabase();if(!wal){writer.getWritableDatabase().disableWriteAheadLogging();reader.getReadableDatabase().disableWriteAheadLogging();}CountDownLatch attempted=new CountDownLatch(1),read=new CountDownLatch(1);AtomicReference<Throwable> failure=new AtomicReference<>();writer.getWritableDatabase().beginTransaction();Thread thread=new Thread(()->{attempted.countDown();try{reader.rows("SELECT id FROM sessions");}catch(Throwable error){failure.set(error);}finally{read.countDown();}},"private-competing-read");try{thread.start();assertTrue(attempted.await(5,TimeUnit.SECONDS));if(wal)assertTrue("Raw WAL reader can finish",read.await(2,TimeUnit.SECONDS));else assertFalse("Default exclusive transaction retains read contention",read.await(200,TimeUnit.MILLISECONDS));}finally{writer.getWritableDatabase().endTransaction();}thread.join(5000);assertFalse(thread.isAlive());assertNull(failure.get());}
    }finally{context.deleteDatabase(name);}}
}
